import re,glob,os
tbl={}
for line in open('draft/numerals.md'):
    m=re.match(r'\|\s*(\d+)\s*\|\s*(.+?)\s*\|',line)
    if m: tbl[m.group(1)]=m.group(2)
print("table",len(tbl),tbl)
text=""
for f in sorted(glob.glob('draft/*.md')):
    if f.endswith('numerals.md'): continue
    text+=open(f).read()
used=set(re.findall(r'\b(\d{2,3})\b',text))
print("in text not in table:",sorted(used-set(tbl)))
print("in table not in text:",sorted(set(tbl)-used))
for f in sorted(glob.glob('figures/*.md')):
    s=open(f).read()
    nums=re.findall(r'\b(\d{2,3})\b',s)
    print(os.path.basename(f), len(s), "chars; numerals:", sorted(set(nums)), "unknown:", sorted(set(nums)-set(tbl)))
for f in sorted(glob.glob('draft/*.md'))+sorted(glob.glob('figures/*.md')):
    s=open(f).read()
    for bad in ['TODO','TBD','[ ]','XXX','placeholder','—','draftsperson','confirm']:
        if bad.lower() in s.lower(): print("MARKER",f,bad)
